head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS05300.xml";
scwin.nPreRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);
    scwin.ins_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "select") {
        dts_CntrInfo.removeAll();
        dts_FornInst.removeAll();
    } else if (pFg == "select_detail") {
        dts_FornInst.removeAll();
    }
};



/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined || pGubun == "select" || pGubun == "select_detail") {
        return true;
    }
    if ($c.stf.getObjectValue(txb_FORN_INST_NM) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "외국기관명"));
        txb_FORN_INST_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_FORN_INST_NM, 60, "외국기관명")) {
        //txb_COM_ENG_NM.value = "";
        txb_FORN_INST_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ACTIV_YN) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "활성여부"));
        cmb_ACTIV_YN.focus();
        return false;
    }
    return true;
};


/**
 * 국가코드조회 조회
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("select");
    $c.stf.setObjectValue(txb_label, "");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("select")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_CntrInfo);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corp.select.listNatCdInquiry" + "&outputMessageId=INS_LIST_NAT_CD_INQUIRY" + "&param01=" + $c.stf.getObjectValue(txb_CNTR_NM);
    dts_CntrInfo.DataID = encodeURI(url);
    dts_CntrInfo.Reset();
};


/**
 * 외국기관 조회
 */
scwin.ins_SearchDetail = function() {
    //데이터셋 초기화
    scwin.fn_InitDs("select_detail");

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("select_detail")) {
        return;
    }
    var CNTR_CD3 = dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD3");
    $c.stf.setObjectValue(txb_label, CNTR_CD3);

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_FornInst);
    var nRow = dts_CntrInfo.getRowPosition();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corp.select.listCorpForeInstInquiry" + "&outputMessageId=INS_LIST_CORP_FORE_INST_INQUIRY" + "&param01=" + dts_CntrInfo.getCellData(nRow, "CNTR_CD") + "&param02=" + $c.stf.getObjectValue(txb_FORN_INST_NM1);
    dts_FornInst.DataID = encodeURI(url);
    dts_FornInst.Reset();
};


/**
 * 신규버튼 클릭
 */
scwin.fn_New = function() {
    if (dts_FornInst.getTotalRow() == 0) {
        scwin.nPreRow = -1;
    }
    dts_FornInst.insertRow();
    txb_CNTR_CD.setValue(dts_CntrInfo.getCellData(dts_CntrInfo.getRowPosition(), "CNTR_CD"));
    cmb_ACTIV_YN.setSelectedIndex(0);
    txb_FORN_INST_NM.focus();
};


/**
 * 외국기관 수정
 */
scwin.ins_Update = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("update")) {
        return;
    }
    if (!confirm("수정하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/OrgInfoAction.do?method=modifyCorpForeInst" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&queryId=lds.ins.corp.update.modifyCorpForeInst";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_FornInst)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Save.Post();
};


/**
 * 외국기관 입력
 */
scwin.ins_Insert = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("insert")) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_Save.Action = "/OrgInfoAction.do?method=registerCorpForeInst" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&queryId=lds.ins.corp.insert.registerCorpForeInst";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_FornInst)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_Save.Post();
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_CntrInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_CntrInfo);
    $c.stf.alert_error(dts_CntrInfo);
};
scwin.dts_CntrInfo_OnLoadCompleted = function(rowcount) {
    if (dts_CntrInfo.errorMsg) {
        $c.win.alert(dts_CntrInfo.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_CntrInfo);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    }
};
scwin.dts_CntrInfo_OnRowPosChanged = function(row) {
    // 조회된 것들은 국가코드 비활성, 신규로 생성된 것만 활성.
    if (dts_CntrInfo.getCellData(row, "CNTR_CD") != "") {
        scwin.ins_SearchDetail();
    }
};
scwin.dts_FornInst_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_FornInst);
    $c.stf.alert_error(dts_FornInst);
};
scwin.dts_FornInst_OnRowPosChanged = function(row) {
    if (row <= 0) {
        return;
    }
    dts_FornInst.undoRow(scwin.nPreRow);
    scwin.nPreRow = row;
    if (dts_FornInst.getCellData(row, "SELECTED") == "Y") {
        fn_CtrlBtn_temp("update");
    } else {
        fn_CtrlBtn_temp("insert");
    }
};
scwin.dts_FornInst_OnLoadCompleted = function(rowcount) {
    if (dts_FornInst.errorMsg) {
        $c.win.alert(dts_FornInst.errorMsg);
    } else {
        txb_TotalCnt2.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_FornInst);

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn_temp("no_data");
    }
};
scwin.btn_search_onclick = function() {
    scwin.ins_Search();
};
scwin.btn_search2_onclick = function() {
    scwin.ins_SearchDetail();
};
scwin.btn_new_onclick = function() {
    scwin.fn_New();
};
scwin.btn_modify_onclick = function() {
    scwin.ins_Update();
};
scwin.btn_save_onclick = function() {
    scwin.ins_Insert();
};
scwin.txb_CNTR_NM_onkeydown = function() {
    fn_DelChar(this);
    if (event.keyCode == 13) {
        scwin.ins_Search();
    }
};
scwin.txb_FORN_INST_NM1_onkeydown = function() {
    fn_DelChar(this);
    if (event.keyCode == 13) {
        scwin.ins_SearchDetail();
    }
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "저장") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_SearchDetail();
};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_SearchDetail();
};
scwin.txb_CNTR_NM_onkeyup = function() {
    fn_DelChar(this);
};
